package com.pathways.rules.content

import com.pathways.model.DiceExpr
import kotlinx.serialization.json.Json

/**
 * Loads the committed content files (under /content/ on the classpath,
 * e.g. /content/skills.json), generated by tools/extract_content.py from
 * the rulebook and the fixture spreadsheets, into typed lists. Each file
 * is parsed at most once per process, via [lazy].
 */
object ContentLoader {

    private val json = Json { ignoreUnknownKeys = true }

    private val skillsLazy: List<SkillDefinition> by lazy { load("skills.json") }
    private val advantagesLazy: List<TraitDefinition> by lazy { load("advantages.json") }
    private val disadvantagesLazy: List<TraitDefinition> by lazy { load("disadvantages.json") }
    private val pathwaysLazy: List<SequenceBlock> by lazy { load("pathways.json") }
    private val actingMethodLazy: List<ActingQuality> by lazy { load("acting_method.json") }
    private val potionConsumptionLazy: List<PcrRow> by lazy { load("potion_consumption.json") }
    private val corGainedLazy: List<CorGain> by lazy { load("cor_gained.json") }
    private val poolThresholdsLazy: List<PoolThreshold> by lazy { load("pool_thresholds.json") }
    private val ritualWeightsLazy: List<RitualWeight> by lazy { load("ritual_weights.json") }
    private val ritualFailuresLazy: List<RitualFailure> by lazy { load("ritual_failures.json") }
    private val ritualSuccessLazy: List<RitualSuccess> by lazy { load("ritual_success.json") }
    private val ritualPreparationLazy: List<RitualPreparation> by lazy {
        load("ritual_preparation.json")
    }
    private val ritualCriticalsLazy: List<RitualCritical> by lazy {
        load<RitualCritical>("ritual_critical.json").sortedBy { it.low }
    }
    private val unarmedAttacksLazy: List<UnarmedAttack> by lazy { load("unarmed_attacks.json") }
    private val rangePenaltiesLazy: List<RangePenalty> by lazy {
        // Sorted so a distance lookup walks the bands nearest-first whatever
        // order the file lists them in -- which is also what settles the
        // book's own overlap at 100 metres. See Ranged.penaltyFor.
        load<RangePenalty>("range_penalties.json").sortedBy { it.from }
    }
    private val rangedModifiersLazy: List<RangedModifier> by lazy { load("ranged_modifiers.json") }
    private val spiritDamageLazy: List<SpiritDamageRule> by lazy { load("spirit_damage.json") }
    private val majorWoundLazy: List<MajorWound> by lazy { load("major_wound.json") }
    private val successLadderLazy: List<SuccessBand> by lazy { load("success_ladder.json") }
    private val commonModifiersLazy: List<CommonModifier> by lazy {
        load("common_modifiers.json")
    }
    private val sequenceImmunityLazy: List<SequenceImmunity> by lazy {
        load("sequence_immunity.json")
    }
    private val antiDivinationCountersLazy: List<AntiDivinationCounter> by lazy {
        load("anti_divination_counters.json")
    }
    private val divinationAwarenessLazy: List<DivinationAwareness> by lazy {
        load("divination_awareness.json")
    }
    private val detectionOutcomesLazy: List<DetectionOutcome> by lazy {
        load("detection_outcomes.json")
    }
    private val detectionModifiersLazy: List<DetectionModifier> by lazy {
        load("detection_modifiers.json")
    }
    private val antiDivinationTechniquesLazy: List<AntiDivinationTechnique> by lazy {
        load("anti_divination_techniques.json")
    }
    private val antiDivinationItemsLazy: List<AntiDivinationItem> by lazy {
        load("anti_divination_items.json")
    }
    private val coreMechanicLazy: List<CoreBand> by lazy { load("core_mechanic.json") }
    private val effortBurnLazy: List<BurnablePool> by lazy { load("effort_burn.json") }
    private val quickContestsLazy: List<QuickContest> by lazy {
        load("quick_contests.json")
    }
    private val skillDefaultsLazy: List<SkillDefault> by lazy {
        load("skill_defaults.json")
    }
    private val spiritualSensesLazy: List<SpiritualSense> by lazy {
        load("spiritual_senses.json")
    }
    private val spiAffinityLazy: List<SpiAffinity> by lazy {
        load("spi_affinity.json")
    }
    private val sealedArtifactGradesLazy: List<SealedArtifactGrade> by lazy {
        load("sealed_artifact_grades.json")
    }
    private val sealedArtifactsLazy: List<SealedArtifact> by lazy {
        load("sealed_artifacts.json")
    }
    private val divinationDifficultyLazy: List<DivinationDifficulty> by lazy {
        load("divination_difficulty.json")
    }
    private val divinationMethodsLazy: List<DivinationMethod> by lazy {
        load("divination_methods.json")
    }
    private val divinationModifiersLazy: List<DivinationModifier> by lazy {
        load("divination_modifiers.json")
    }
    private val divinationClarityLazy: List<DivinationClarity> by lazy {
        load("divination_clarity.json")
    }
    private val divinationSupportLazy: List<DivinationSupport> by lazy {
        load("divination_support.json")
    }
    private val nonStandardPathwaysLazy: List<SequenceBlock> by lazy {
        // A SEPARATE file from pathways.json on purpose: these advance by
        // boon, not potion, and PotionDigestion walks whatever pathways.json
